import Image from 'next/image'

const logoUrl = '/fsudolablogo.webp'
const partnerRows = [
  { direction: 'right' as const, labels: ['Your company', 'Partner logo', 'Company logo', 'New partner', 'Future partner'], featuredImage: '/partners/meta.webp' },
  { direction: 'left' as const, labels: ['Add logo here', 'Partner mark', 'Company logo', 'Collaborator', 'Client logo'] },
]

export function PartnersSection() {
  return (
    <section id="partners" className="overflow-hidden border-t border-[#ebe8f1] bg-white py-16 lg:py-24">
      <div className="mx-auto max-w-7xl px-6 lg:px-10">
        <p className="text-sm font-semibold uppercase tracking-[0.18em] text-[#a329c8]">Trusted collaborations</p>
        <h2 className="mt-3 text-3xl font-semibold tracking-[-0.04em] text-[#1c1e44]">People we build with</h2>
        <p className="mt-3 max-w-lg text-sm leading-6 text-[#5a5b70]">A growing circle of ambitious teams. Replace each placeholder with a partner mark whenever you&apos;re ready.</p>
      </div>
      <div className="mt-12 flex flex-col gap-7">
        {partnerRows.map((row) => <LogoMarquee key={row.direction} direction={row.direction} labels={row.labels} featuredImage={row.featuredImage} />)}
      </div>
    </section>
  )
}

function LogoMarquee({ direction, labels, featuredImage }: { direction: 'left' | 'right'; labels: string[]; featuredImage?: string }) {
  const items = [...labels, ...labels]
  return (
    <div className="group relative overflow-hidden">
      <div className={`flex w-max ${direction === 'left' ? 'animate-marquee-left' : 'animate-marquee-right'} group-hover:[animation-play-state:paused]`}>
        {items.map((label, index) => <PartnerLogo key={`${label}-${index}`} label={label} image={featuredImage && index % labels.length === 0 ? featuredImage : undefined} />)}
      </div>
    </div>
  )
}

function PartnerLogo({ label, image = logoUrl }: { label: string; image?: string }) {
  return (
    <div className="flex h-24 w-[20vw] min-w-44 shrink-0 items-center justify-center border-r border-[#e6e2ec] px-10 transition">
      <Image src={image} alt={`${label} logo`} width={110} height={62} className="h-12 w-auto object-contain mix-blend-multiply opacity-65" />
      <span className="sr-only">{label}</span>
    </div>
  )
}
